  'about.bookshopLeadIn': "Dibuat oleh usaha kecil yang sama yang menjalankan toko buku kami:",
  "about.eyebrow": "Tentang Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — Tentang Kami",
  "about.founderHeading": "📖 Tentang Pendiri",
  "about.founder.p1": "Halo, saya Concepcion, pendiri Luminous StockHaven.",
  "about.founder.p2": "Saya tidak berasal dari perusahaan teknologi besar, dan saya tidak duduk di kantor korporat. Saya adalah pemilik ritel kecil, sama seperti Anda. Saya mengelola lima toko e-commerce yang berspesialisasi dalam buku dan aksesori buatan tangan untuk para pencinta buku.\nSeperti banyak peritel independen, saya mencapai titik jenuh ketika mencoba mengelola inventaris di banyak lokasi, melacak ISBN penerbit di samping SKU buatan tangan saya sendiri, dan menangani pesanan pemasok dengan spreadsheet yang rumit. Ketika saya mencari aplikasi untuk membantu saya, saya mencoba enam pilihan berbeda. Masing-masing benar-benar tidak lengkap, sangat membingungkan, atau predatoris — mengenakan biaya ratusan dolar per bulan untuk alat-alat dasar.",
  "about.founder.p3": "Frustrasi dengan industri yang memeras kreator independen, saya memutuskan untuk membangun solusi saya sendiri. Saya membangun Luminous StockHaven karena kebutuhan, untuk menjalankan bisnis saya sendiri dengan bersih, efisien, dan dengan ketenangan pikiran penuh.",
  "about.founder.p4": "Saya memutuskan untuk membuka platform ini kepada publik dengan harga yang jujur dan terjangkau, karena setiap pemilik usaha kecil berhak mendapatkan alat yang benar-benar berfungsi tanpa mempertaruhkan penghasilannya. Kami dimiliki secara independen, sangat melindungi komunitas kami, dan dibangun oleh seorang peritel, untuk para peritel.",
