  "plans.title": "Bandingkan paket StockHaven",
  "plans.intro": "Satu akun, paket apa pun yang Anda pilih — Bisnis mencakup hingga lima bisnis. Harga bulanan dalam dolar AS, dan pelanggan situs web baru yang memenuhi syarat dapat menerima satu uji coba tujuh hari di Essentials dan Business. Mengupgrade langganan Essentials ke Business yang sudah ada tidak memulai ulang uji coba atau membuat uji coba gratis lainnya. Harga paket situs web adalah sebelum pajak yang berlaku, jika ada. Tagihan persis Anda akan ditampilkan sebelum Anda mengotorisasi langganan.",
