  "upgrade.providerConfirmNote": "Perubahan paket memerlukan konfirmasi dari penyedia penagihan. Perbedaan harga, prorata, dan tanggal efektif harus ditampilkan sebelum Anda menyetujui perubahan. Peningkatan versi tidak boleh membuat langganan kedua secara bersamaan.",
  "upgrade.chargedThroughProviderNote": "Perubahan paket dibebankan melalui penyedia penagihan. Anda dapat membatalkan langganan dari halaman ini menggunakan tombol Batalkan Berlangganan di paket Anda saat ini, atau dari Pengaturan. Pembatalan menghentikan perpanjangan masa depan pada akhir periode pembayaran Anda; itu tidak pernah mengakhiri akses Anda sekaligus. Ruang kerja gratis yang ada tidak dikenakan biaya dengan melihat opsi ini.",
