  'settings.details.taxRate': 'Tarif pajak saya',
  'settings.details.taxRateHint': 'Atur sekali. Setiap pesanan penjualan baru mengisi pajaknya sendiri dari tarif ini — Anda tetap bisa mengubah pajak pada satu pesanan mana pun.',
  "settings.details.taxMode": "Cara pesanan mendapatkan pajaknya",
  "settings.details.taxModeFixed": "Tarif tetap saya",
  "settings.details.taxModeAutomatic": "Otomatis — berdasarkan negara bagian pelanggan",
  "settings.details.taxModeHint": "Mode tetap menggunakan tarif Anda pada setiap pesanan baru. Mode otomatis mengisi pajak pesanan baru dengan tarif dasar negara bagian pelanggan begitu negara bagian ada pada pesanan, dan mengisinya lagi jika negara bagian berubah. Ini adalah tarif dasar negara bagian — pajak daerah dapat menambah lebih banyak. Pesanan tanpa negara bagian, atau dari luar AS, menggunakan tarif tetap Anda di atas.",
  'settings.details.gs1Prefix': "Awalan perusahaan GS1",
  'settings.details.gs1PrefixHint': "Hanya jika Anda memiliki lisensi awalan dari GS1. Atur sekali dan generator kode di formulir produk dapat membuat kode UPC dan EAN eceran asli dari nomor Anda sendiri — masing-masing dipakai satu kali saja dan tidak pernah dipakai ulang. Biarkan kosong jika Anda tidak memilikinya; aplikasi tidak pernah mengarang awalan.",
  'settings.details.gs1LearnMore': "Baru mengenal GS1? Jika Anda tinggal di negara Anda sendiri, gunakan tautannya untuk mempelajari lebih lanjut; jika Anda tinggal di Amerika Serikat, gunakan tautan GS1 US.",
