  "settings.pastDue.body": "Pembayaran terakhir Anda tidak berhasil. Anda tetap mendapat penggunaan penuh selama 14 hari sejak pembayaran yang gagal selama Anda memperbaikinya. Jika tidak diperbaiki, langganan akan dibatalkan, ruang kerja menjadi hanya-lihat selama 15 hari, lalu akun dan semua informasinya dihapus. Membayar kapan pun sebelum penghapusan mengembalikan semuanya. Jika Anda tidak yakin harus berbuat apa, hubungi dukungan di theluminousbookshop@outlook.com.",
