  "print.recipientAddressLabel": "Alamat penerima",
  "print.senderAddressLabel": "Alamat Anda (pengirim)",
  "print.shippingNote": "Jika pesanan memiliki alamat pengiriman, alamat itu terisi dari pesanan. Apa yang Anda ketik di sini dicetak sekali dan tidak pernah disimpan kembali.",
  "print.carrier.title": "Label pengiriman Anda",
  "print.carrier.desc": "Beli ongkos kirim dari pengangkut, seperti yang Anda lakukan hari ini — aplikasi ini tidak pernah menjual ongkos kirim, jadi harga yang Anda bayar selalu harga pengangkut itu sendiri. Simpan file label di sini dan label itu tetap pada pesanan ini selamanya: catatan Anda, siap di tangan untuk berjaga-jaga jika terjadi sesuatu.",
