  "training.lessons.owner-shipping-labels.step1": "Pusat Cetak memiliki gaya Label pengiriman di kedua paket: pilih pesanan pelanggan dan cetak label 4×6 dengan nama dan alamat pembeli serta bisnis Anda sebagai pengirim.",
  "training.lessons.owner-shipping-labels.step2": "Label ini berlabel putih, seperti setiap dokumen pelanggan: hanya memuat nama bisnis Anda — tidak pernah nama aplikasi ini — sehingga paket dari toko Anda tampak berasal dari toko Anda.",
  "training.lessons.owner-shipping-labels.step3": "Alamat pelanggan disimpan bersama pesanan mereka selama 90 hari setelah pesanan terakhir mereka, dan label dimulai dari alamat tersimpan pesanan saat ada; alamat yang diketik saat pencetakan untuk label sekali pakai tidak disimpan kembali. Nama tetap terisi dari pesanan sehingga label cocok dengan dokumen.",
  "training.lessons.owner-shipping-labels.step4": "Label ini dicetak melalui empat koneksi yang sama dengan semua label — Bluetooth, Wi-Fi, Ethernet, dan USB — dan printer termal 4×6 adalah ukuran standarnya.",
  "training.lessons.owner-shipping-labels.step5": "Membeli ongkos kirim dari pengangkut sebagai gantinya? Di bagian yang sama ini Anda dapat mengunggah file label pengangkut — PDF, PNG, atau JPG — dan label itu tetap tersimpan pada pesanan selamanya: catatan Anda, siap di tangan untuk berjaga-jaga jika terjadi sesuatu. Label tercetak dalam ukuran aslinya 4×6. Aplikasi tidak pernah menjual ongkos kirim, jadi harga pengangkut adalah satu-satunya harga — dan selalu harga yang benar.",
  "training.lessons.owner-shipping-labels.title": "Label pengiriman untuk pesanan pelanggan",
  "training.lessons.print-shipping-label.step1": "Ketika pesanan siap dikirim, buka Pusat Cetak, pilih gaya Label pengiriman, lalu pilih pesanan pelanggan. Nama pembeli terisi dari pesanan.",
  "training.lessons.print-shipping-label.step2": "Periksa alamat tujuan paket. Saat pesanan membawa alamat pelanggan — disimpan selama 90 hari setelah pesanan terakhir mereka — itu terisi untuk Anda; alamat yang Anda ketik saat pencetakan tidak disimpan kembali, jadi periksa kode pos dan baris terakhir dengan hati-hati sebelum mencetak.",
  "training.lessons.print-shipping-label.step3": "Nama bisnis Anda tercetak di atas sebagai pengirim. Jika Anda ingin alamat Anda juga ada di label, ketik di kotak alamat pengirim; biarkan kosong jika Anda lebih suka tidak ditampilkan.",
  "training.lessons.print-shipping-label.step4": "Cetak pada label 4×6 — printer label termal adalah pilihan yang biasa — atau pada printer apa pun melalui tombol cetak browser. Tempelkan label rata pada paket, di tempat yang tidak terlipat di tepi.",
  "training.lessons.print-shipping-label.step5": "Jika ongkos kirim dibeli dari pengangkut, simpan file label mereka pada pesanan sebagai gantinya: unggah PDF, PNG, atau JPG yang diberikan pengangkut kepada Anda di bagian Label pengiriman Anda. Label itu tetap pada pesanan sebagai catatan Anda dan tercetak dalam ukuran aslinya 4×6 — dan label alamat aplikasi sendiri selalu ada di sana saat Anda lebih suka menggunakannya.",
  "training.lessons.print-shipping-label.title": "Cetak label pengiriman",
  "pos.provider.clover": "Clover",
