  "training.lessons.staff-shift-windows.title": "Proses masuk Anda mengikuti shift Anda",
  "training.lessons.staff-shift-windows.step1": "Anda dapat masuk mulai sekitar 10 menit sebelum shift terjadwal Anda dimulai. Sebelum itu, aplikasi tetap tertutup — halaman masuk akan memberi tahu Anda kapan shift Anda berikutnya dimulai.",
  "training.lessons.staff-shift-windows.step2": "Setelah Anda absen keluar, Anda punya 10 menit untuk memeriksa halaman Anda, karena Anda akan dikeluarkan hingga tanggal terjadwal berikutnya.",
  "training.lessons.staff-shift-windows.step3": "Jika Anda absen masuk lagi dalam 10 menit itu, proses keluar dibatalkan dan Anda tetap masuk.",
  "training.lessons.staff-shift-windows.step4": "Tidak ada shift pada jadwal berarti tidak bisa masuk pada hari itu. Jika Anda merasa seharusnya ada di jadwal, tanyakan kepada manajer atau pemilik Anda — merekalah yang menerbitkan jadwal yang membuka pintu Anda.",
  "training.lessons.manager-shift-windows.title": "Menerbitkan jadwal membuka dan menutup akses",
  "training.lessons.manager-shift-windows.step1": "Jadwal yang Anda terbitkan untuk tim Anda lebih dari daftar shift: itulah yang membuka dan menutup akses aplikasi setiap orang. Anggota tim dapat masuk mulai sekitar 10 menit sebelum shift yang Anda terbitkan untuknya — dan tidak sebelumnya.",
  "training.lessons.manager-shift-windows.step2": "Ketika ia absen keluar, ia punya sekitar 10 menit untuk memeriksa jamnya, lalu aplikasi mengeluarkannya hingga shift terjadwal berikutnya. Tidak ada shift yang diterbitkan pada hari itu berarti ia tidak dapat masuk pada hari itu.",
  "training.lessons.manager-shift-windows.step3": "Terbitkan shift dengan hati-hati: shift yang hilang atau salah mengunci seseorang di luar aplikasi, bukan hanya di luar jadwal. Jika seseorang mengatakan ia tidak bisa masuk, periksa dulu jadwalnya.",
  "training.lessons.manager-shift-windows.step4": "Akses Anda sendiri bekerja dengan cara yang sama, satu tingkat di atas: jadwal yang diterbitkan pemilik untuk Anda membuka jendela Anda sekitar 10 menit sebelum shift Anda, dan sesi Anda ditutup sekitar 10 menit setelah Anda absen keluar.",
  "training.lessons.owner-shift-windows.title": "Jendela shift: jadwal membuka dan menutup akses",
  "training.lessons.owner-shift-windows.step1": "Akses mengikuti jadwal yang Anda terbitkan. Staf atau manajer dapat masuk mulai sekitar 10 menit sebelum shift terjadwalnya — dan tidak sebelumnya. Di luar shift, aplikasi tetap tertutup bagi mereka, agar informasi toko tetap pada orang yang sedang bertugas.",
  "training.lessons.owner-shift-windows.step2": "Ketika mereka absen keluar, mereka punya sekitar 10 menit untuk memeriksa jam mereka, lalu aplikasi mengeluarkan mereka dengan sendirinya hingga shift terjadwal berikutnya. Absen masuk lagi dalam 10 menit itu membatalkan proses keluar.",
  "training.lessons.owner-shift-windows.step3": "Tidak ada shift yang diterbitkan pada hari itu berarti tidak ada jendela pada hari itu: jika seseorang tidak ada di jadwal, ia tidak dapat masuk. Terbitkan jadwal di Tenaga Kerja dan pintunya terbuka bersamanya.",
  "training.lessons.owner-shift-windows.step4": "Anda adalah satu-satunya pengecualian: tidak ada yang menjadwalkan pemilik, jadi proses masuk Anda tidak pernah berjendela. Seorang manajer dibatasi oleh jadwal yang Anda terbitkan untuknya, sama seperti staf dibatasi oleh jadwal yang diterbitkan untuk mereka.",
  "settings.install.ownerNote": "Jika toko aplikasi Anda suatu hari menghalangi Anda menggunakan aplikasi, tautan ini memberi Anda aplikasi langsung dari situs web ini — tidak perlu toko.",
  "layout.signOutLink": "Keluar",
  "plansLib.includes.teamSettings": "Pengaturan pribadi dan keluar untuk setiap anggota tim",
  "plansLib.includes.shiftWindows": "Akses terikat shift — aplikasi terbuka 10 menit sebelum shift terjadwal dan keluar setelah absen pulang",
  "plansLib.includes.ownerOnlyBilling": "Pemberitahuan uji coba dan penagihan hanya untuk pemilik — tidak pernah ditampilkan ke staf",
