  "plansLib.includes.inviteLink": "Undangan staf dengan tautan pendaftaran satu ketukan",
  "subscribe.memberNote": "Anda masuk sebagai anggota ruang kerja ini. Halaman ini milik pemilik bisnis — jika Anda membutuhkan sesuatu di sini, mintalah kepadanya.",
  "subscribe.memberOpenApp": "Buka aplikasi",
  "apiErrors.planLimitNeutral": "Ini tidak dapat ditambahkan sekarang — mintalah kepada pemilik bisnis.",
  "training.lessons.owner-confidentiality.title": "Informasi Anda tetap rahasia",
  "training.lessons.owner-confidentiality.step1": "Luminous StockHaven menjaga informasi Anda tetap rahasia dari staf Anda. Pembayaran Anda, uji coba Anda, langganan Anda dan status penagihan Anda — dan apa pun tentang informasi pribadi Anda — adalah milik Anda sendiri: staf dan manajer tidak pernah melihatnya, di mana pun di aplikasi.",
  "training.lessons.owner-confidentiality.step2": "Itu termasuk tempat-tempat yang sepi: tidak ada hitung mundur uji coba di atas halaman mereka, tidak ada bagian paket atau penagihan di Pengaturan mereka, tidak ada peringatan pembayaran. Pengaturan mereka bersifat pribadi — akun mereka sendiri, keamanan, tampilan dan bahasa — ditambah hanya bagian tambahan yang Anda centang untuk mereka. Penagihan tidak pernah menjadi salah satu centang.",
  "training.lessons.owner-confidentiality.step3": "Jika akun suatu hari dihentikan karena alasan penagihan, staf Anda tidak akan pernah diberi tahu alasannya. Mereka hanya melihat pemberhentian yang sederhana dan netral — perubahan sedang dimatikan saat ini — sehingga Anda dapat menjelaskannya kepada tim Anda sendiri dengan kata-kata Anda sendiri.",
  "training.lessons.owner-confidentiality.step4": "Dan jika Anda suatu hari melihat sesuatu yang ditampilkan kepada staf Anda yang seharusnya tidak ditampilkan — kebocoran apa pun — buka Pengaturan dan ketuk Laporkan masalah untuk memberi tahu kami, agar kami dapat memperbaikinya sesegera mungkin.",
  "staffLib.perm.settingsContactDetails": "Detail kontak bisnis (alamat & telepon)",
  "staff.memberDialog.contactDetailsHint": "Khusus manajer — centang ini berlaku untuk manajer. Staf tidak pernah mengedit alamat atau nomor telepon.",
  "settings.businessCard.title": "Tentang bisnis ini",
  "settings.businessCard.address": "Alamat",
  "settings.businessCard.phone": "Telepon",
  "settings.businessCard.empty": "Belum ada alamat atau nomor telepon yang ditambahkan.",
  "staff.memberDialog.personalAddress": "Alamat rumah",
  "staff.memberDialog.personalPhone": "Nomor telepon",
  "workforce.messages.voiceNote": "Catatan suara",
  "workforce.messages.recording": "Merekam…",
  "workforce.messages.stopRecording": "Berhenti",
  "workforce.messages.voiceReady": "Catatan suara Anda siap. Dengarkan, lalu kirim — atau hapus dan rekam lagi.",
  "workforce.messages.sendVoice": "Kirim catatan suara",
  "workforce.messages.discard": "Hapus",
  "workforce.messages.micDenied": "Mikrofon diblokir, jadi catatan suara tidak dapat direkam. Anda dapat mengizinkan mikrofon di pengaturan browser — atau cukup kirim pesan tertulis.",
  "workforce.messages.voiceFailed": "Catatan suara itu tidak dapat dikirim. Silakan coba lagi.",
  "workforce.messages.sentLabel": "Terkirim",
  "workforce.messages.receivedLabel": "Diterima",
  "workforce.messages.readLabel": "Dibaca",
  "apiErrors.notFound.voiceNoteFound": "Catatan suara tidak ditemukan.",
  "apiErrors.invalidValue.sendVoiceRecording": "Kirim rekaman suara paling lama beberapa menit.",
  "apiErrors.invalidValue.recordingNotPrepared": "Rekaman itu tidak dapat disiapkan — silakan rekam lagi.",
  "training.lessons.messages-private.step5": "Anda juga dapat mengirim catatan suara: ketuk mikrofon di samping kotak pesan, bicara, lalu ketuk berhenti. Dengarkan dulu — lalu kirim, atau hapus dan rekam lagi. Saat seseorang mengirimkannya kepada Anda, ketuk putar untuk mendengar suara aslinya.",
  "training.lessons.owner-messages-oversight.step5": "Tanda dibaca: saat anggota tim membaca pesan yang Anda kirimkan, Anda melihatnya ditandai telah dibaca. Staf dan manajer melihat tanda dibaca satu sama lain dengan cara yang sama, dua arah.",
  "training.lessons.owner-messages-oversight.step6": "Bacaan Anda sendiri tidak terlihat. Saat Anda membaca pesan yang dikirim anggota staf kepada Anda, mereka tidak pernah melihat tanda dibaca — dan Anda tidak perlu memberi tahu tim Anda bahwa percakapan mereka tersimpan di aplikasi dan bahwa Anda, pemiliknya, dapat membacanya. Pengawasan itu bagian dari menjaga toko Anda.",
  "training.lessons.owner-messages-oversight.step7": "Apa yang Anda lakukan terhadap pesan negatif antaranggota staf terserah Anda. Biarkan saja, bicaralah dengan seseorang secara pribadi, atau ambil tindakan — pilihan ada di tangan Anda, dan Anda tidak pernah harus mengatakan di mana Anda melihatnya.",
  "staffLib.perm.returnsComplete": "Menyelesaikan pengembalian dana dan penukaran",
  "staffLib.area.returnsAccess": "Persetujuan retur",
  "staff.memberDialog.returnsAccessHint": "Dengan centang ini, orang ini dapat menyetujui retur dan menyelesaikan pengembalian dana atau penukaran. Tanpa centang ini, retur yang ia mulai menunggu pemilik atau anggota tim yang disetujui.",
  "returns.waitingApproval": "Menunggu persetujuan dari pemilik atau anggota tim yang disetujui.",
  "returns.waitingToFinish": "Disetujui — pemilik atau anggota tim yang disetujui akan menyelesaikan retur ini.",
  "apiErrors.returnsCompleteReserved": "Hanya pemilik, atau anggota tim yang diizinkan pemilik untuk menyelesaikan pengembalian dana dan penukaran, yang dapat menyetujui dan menyelesaikan retur.",
  "staffLib.perm.productsCreate": "Tambahkan produk baru",
  "staffLib.area.productsAccess": "Menambahkan produk",
  "staff.memberDialog.productsAccessHint": "Dengan centang ini, orang ini melihat tombol Produk baru dan dapat menambahkan produk ke katalog. Tanpa centang ini, tombol-tombol itu tidak muncul untuk mereka.",
  "productForm.readIsbnTitle": "Baca ISBN yang tercetak",
  "productForm.readIsbnHint": "Arahkan kamera ke ISBN yang tercetak di buku, lalu ketuk Baca nomor. Jika barcode bisa dibaca, barcode itu juga mengisi nomornya.",
  "productForm.readIsbnButton": "Baca nomor",
  "productForm.readIsbnWorking": "Membaca nomor…",
  "productForm.readIsbnFailed": "Nomor itu tidak terbaca dengan jelas, jadi tidak ada yang terisi. Coba lagi, atau tutup ini dan ketik nomornya.",
  "staffLib.perm.locationsCreate": "Tambahkan lokasi baru",
  "staffLib.area.locationsAccess": "Menambahkan lokasi",
  "staff.memberDialog.locationsAccessHint": "Dengan centang ini, orang ini dapat menambahkan lokasi baru. Tanpa centang ini, hanya pemilik yang dapat menambahkan lokasi, dan tombol tambah tidak muncul untuk mereka.",
  "apiErrors.locationsCreateReserved": "Hanya pemilik, atau anggota tim yang diizinkan pemilik untuk menambahkan lokasi, yang dapat menambahkan lokasi.",
  "settings.policies.title": "Kebijakan & ketentuan toko Anda",
  "settings.policies.ownerDescription": "Toko Anda, aturan Anda. Tulis kebijakan toko Anda dan syarat & ketentuan Anda di sini — ketik, atau unggah sebuah berkas. Setiap anggota tim baru melihatnya sekali saat mereka mulai, dan seluruh tim Anda dapat membacanya di sini kapan saja. Hanya Anda yang dapat mengubahnya.",
  "settings.policies.memberDescription": "Kebijakan dan ketentuan toko Anda sendiri, ditulis oleh pemilik. Hanya pemilik yang dapat mengubahnya.",
  "settings.policies.storePolicies": "Kebijakan Toko",
  "settings.policies.termsConditions": "Syarat & Ketentuan",
  "settings.policies.policiesHint": "Aturan rumah untuk toko Anda — bagaimana toko dijalankan dan bagaimana aplikasi digunakan di dalamnya. Seluruh kebijakan toko Anda dapat tinggal di sini.",
  "settings.policies.termsHint": "Syarat & ketentuan toko Anda sendiri, dengan kata-kata Anda sendiri.",
  "settings.policies.policiesPlaceholder": "Ketik kebijakan toko Anda…",
  "settings.policies.termsPlaceholder": "Ketik syarat & ketentuan Anda…",
  "settings.policies.uploadFile": "Unggah berkas",
  "settings.policies.replaceFile": "Ganti berkas",
  "settings.policies.removeFile": "Hapus berkas",
