  "settings.policies.openFile": "Buka berkas",
  "settings.policies.fileTypes": "Berkas PDF, teks, Word atau OpenDocument, hingga 2 MB.",
  "settings.policies.badType": "Jenis berkas itu tidak dapat disimpan di sini. Gunakan berkas PDF, teks, Word atau OpenDocument.",
  "settings.policies.tooLarge": "Berkas itu lebih dari 2 MB.",
  "settings.policies.orUpload": "atau unggah berkas sebagai gantinya:",
  "settings.policies.orWrite": "atau tulis di sini sebagai gantinya:",
  "settings.platformPolicies.title": "Kebijakan Luminous StockHaven",
  "settings.platformPolicies.description": "Syarat dan kebijakan aplikasi itu sendiri. Keduanya tetap bersama aplikasi, dan semua orang di tim dapat membacanya di sini.",
  "staffWelcome.policiesIntro": "Sebelum Anda mulai: kebijakan dan ketentuan toko Anda, ditulis oleh pemilik.",
  "plansLib.includes.storePolicies": "Kebijakan dan ketentuan toko Anda sendiri di Pengaturan, untuk dibaca seluruh tim Anda",
  "apiErrors.businessPoliciesOwnerOnly": "Hanya pemilik yang dapat mengubah kebijakan dan ketentuan toko ini.",
  "apiErrors.policyFileInvalid": "Kirim berkas PDF, teks, Word atau OpenDocument di bawah 2 MB.",
  "apiErrors.policyTextTooLong": "Dokumen itu terlalu panjang untuk diketik di sini. Anda dapat mengunggahnya sebagai berkas sebagai gantinya.",
  "training.lessons.owner-store-policies.title": "Kebijakan & ketentuan toko Anda",
  "training.lessons.owner-store-policies.step1": "Buka Pengaturan dan temukan kartu Kebijakan & ketentuan toko. Kartu itu memuat dua dokumen: Kebijakan Toko Anda — aturan rumah untuk toko Anda — dan Syarat & Ketentuan Anda.",
  "training.lessons.owner-store-policies.step2": "Setiap dokumen dapat diketik langsung di sana, atau diunggah sebagai berkas (PDF, teks, Word atau OpenDocument, hingga 2 MB). Salah satu saja: menyimpan teks menggantikan berkas, dan mengunggah berkas menggantikan teks. Menghapus dokumen akan mengosongkannya.",
  "training.lessons.owner-store-policies.step3": "Tim Anda melihat kedua dokumen itu sekali, di halaman sambutan mereka saat pertama kali mulai, dan dapat membacanya kapan saja di Pengaturan mereka. Bagi tim Anda dokumen itu hanya-baca — hanya Anda yang dapat menulis atau mengubahnya.",
  "training.lessons.owner-store-policies.step4": "Setiap bisnis menyimpan dokumennya sendiri: apa yang Anda tulis di sini hanya milik toko ini dan tidak pernah muncul di bisnis lain. Syarat dan kebijakan Luminous StockHaven sendiri tinggal di Pengaturan di samping milik Anda, dan semua orang dapat membacanya juga.",
  "training.lessons.welcome-basics.step5": "Kebijakan dan ketentuan toko Anda ditampilkan sekali di halaman sambutan Anda, dan tinggal di Pengaturan, tempat Anda dapat membacanya kapan saja.",
  "apiErrors.policyDocNotFound": "Dokumen itu bukan salah satu dari keduanya.",
  "apiErrors.policyFileNotFound": "Tidak ada berkas yang disimpan untuk dokumen itu.",
  "staffLib.perm.staffRoster": "Lihat daftar staf lengkap",
  "staffLib.area.staffAccess": "Daftar staf",
  "staff.memberDialog.staffAccessHint": "Khusus manajer — dengan centang ini, manajer ini melihat daftar staf lengkap, hanya untuk dibaca. Tanpa centang ini, seorang manajer hanya melihat kartu mereka sendiri. Centang ini tidak berpengaruh untuk staf.",
  "workforce.schedule.clear": "Hapus",
