  "apiErrors.notFound.photoFound": "Foto tidak ditemukan.",
  "apiErrors.profileOwnerNameOnly": "Hanya pemilik bisnis yang dapat mengatur nama pemilik.",
  "apiErrors.profilePhotosApproveOwnerOnly": "Hanya pemilik bisnis yang dapat menyetujui foto tim.",
