  "apiErrors.profileOwnerNameTooLong": "Nama Anda maksimal 80 karakter.",
  "training.lessons.your-profile-photo.title": "Foto profil Anda",
  "training.lessons.your-profile-photo.step1": "Foto Anda muncul di samping nama Anda di bagian atas aplikasi, di halaman Staf, dan di samping pesan Anda — setelah pemilik menyetujuinya. Sampai saat itu, hanya inisial Anda yang tampil.",
  "training.lessons.your-profile-photo.step2": "Buka Pengaturan dan temukan Foto profil Anda. Pilih foto diri Anda dan kirimkan. Foto itu dikirim ke pemilik untuk disetujui — foto itu tidak muncul di mana pun selama menunggu.",
  "training.lessons.your-profile-photo.step3": "Ketika pemilik menyetujuinya, lonceng Anda berbunyi dan foto Anda mulai tampil. Jika tidak disetujui, pilih foto lain dan kirimkan foto itu sebagai gantinya.",
  "training.lessons.your-profile-photo.step4": "Mengganti foto Anda bekerja dengan cara yang sama: foto baru menunggu persetujuan, dan foto Anda saat ini tetap terpasang sampai foto baru disetujui. Jika perubahan tidak disetujui, Anda tetap memakai foto lama Anda.",
  "training.lessons.owner-profile-photos.title": "Foto profil dan nama Anda",
  "training.lessons.owner-profile-photos.step1": "Foto setiap orang tampil di samping nama mereka di bagian atas aplikasi, di halaman Staf Anda, dan di samping pesan mereka. Foto anggota tim tidak muncul di mana pun sampai Anda menyetujuinya — persetujuan hanya milik Anda, dan tidak ada yang dapat menyetujui foto mereka sendiri.",
  "training.lessons.owner-profile-photos.step2": "Ketika seseorang mengirim foto, lonceng Anda berbunyi. Buka halaman Staf untuk melihatnya, lalu pilih Setujui atau Tidak disetujui. Jika Anda tidak menyetujuinya, orang tersebut diberi tahu untuk memilih foto lain.",
  "training.lessons.owner-profile-photos.step3": "Jika seseorang mengganti fotonya, foto baru menunggu persetujuan Anda dengan cara yang sama. Foto mereka saat ini tetap terpasang selama menunggu — dan tetap terpasang jika Anda tidak menyetujui perubahan itu.",
  "training.lessons.owner-profile-photos.step4": "Foto Anda sendiri tidak memerlukan persetujuan: atur di Pengaturan, di bagian Foto profil Anda. Kartu yang sama memuat nama Anda — nama yang Anda atur di sana menggantikan kata Pemilik di mana pun tim Anda melihatnya, di aplikasi dan di Pesan.",
