  "payroll.dd.correctedDone": "Detail Anda yang diperbaiki telah dikirim ke pemilik.",
  "payroll.dd.correctionNotice": "Pemilik telah mengirim kembali formulir Anda agar Anda dapat memperbaikinya. Periksa setiap digit, tanda tangani, dan kirim kembali.",
  "payroll.dd.correctionWaiting": "Dikirim kembali — menunggu formulir mereka yang diperbaiki",
  "payroll.dd.fixHelp": "Jika ada digit yang salah, perbaiki detail Anda dan kirim kembali formulirnya. Formulir baru Anda yang bertanda tangan menggantikan yang lama, dan pemilik diberi tahu bahwa formulir itu telah diperbaiki.",
