  "payroll.dd.signHelp": "Ketik nama Anda, lalu pilih bagaimana tanda tangan Anda terlihat. Ini adalah tanda tangan elektronik Anda — tanda tangan itu ditempatkan pada formulir setoran langsung Anda persis seperti yang ditampilkan di sini.",
