  "apiErrors.clockFix.breakOutside": "Waktu istirahat harus berada di antara waktu clock in dan clock out.",
  "apiErrors.clockFix.invalidTime": "Kirim setiap waktu sebagai tanggal dan waktu yang valid.",
  "apiErrors.notFound.timeEntryFound": "Catatan waktu tidak ditemukan.",
  "training.lessons.mgr-clock-callin.title": "Panggilan masuk dan koreksi jam",
  "training.lessons.mgr-clock-callin.step1": "Pemilik dapat memberikan satu centang kepada manajer — Panggilan masuk & koreksi jam. Dengannya, Anda dapat membuka jendela panggilan masuk untuk anggota staf dan mengoreksi catatan waktu dari halaman Staf.",
  "training.lessons.mgr-clock-callin.step2": "Jendela panggilan masuk membiarkan seseorang masuk dan clock in saat tidak ada shift yang mencakup mereka. Buka dari halaman Staf, pada kartu Panggilan masuk & clock out terlewat.",
  "training.lessons.mgr-clock-callin.step3": "Jendela tetap terbuka sampai orang itu clock out — kemudian mengikuti masa tenggang keluar 10 menit seperti biasa — atau sampai Anda atau pemilik menutupnya lebih awal. Tidak ada yang menutupnya sendiri.",
  "training.lessons.mgr-clock-callin.step4": "Saat seseorang lupa clock out, catatannya ditandai di halaman Staf dan di Penggajian segera setelah shift terjadwal berakhir, dan Anda serta pemilik diberi tahu. Catatan terus menghitung sampai dikoreksi.",
  "training.lessons.mgr-clock-callin.step5": "Koreksi catatan dari halaman Staf: atur clock in, clock out, dan waktu istirahat. Manajer hanya mengoreksi catatan staf — catatan manajer sendiri dikoreksi oleh pemilik.",
  "staffLib.perm.staffDocuments": "Dokumen staf",
  "staffLib.area.documentsAccess": "Dokumen staf",
  "staff.memberDialog.documentsAccessHint": "Khusus manajer — dengan centang ini, manajer ini dapat membuka berkas dokumen anggota staf: dokumen yang disimpan untuk setiap orang, seperti formulir W-4, lamaran kerja, dan salinan kartu identitas. Anda akan diminta mengonfirmasi terlebih dahulu — berkas ini berisi nomor Jaminan Sosial dan tanggal lahir. Centang ini tidak berpengaruh apa pun untuk staf.",
  "staff.documentsWarning.body": "Orang ini akan dapat melihat informasi rahasia tentang anggota staf Anda, termasuk nomor Jaminan Sosial dan tanggal lahir.",
  "staff.documentsWarning.confirm": "Ya, saya mengerti",
